import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  CircleGeometry,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  Color,
  Vector2,
} from 'three/webgpu';
import {
  uv,
  position,
  add,
  sub,
  mul,
  div,
  mix,
  length,
  abs,
  min,
  max,
  smoothstep,
  step,
  mod,
  float,
  vec2,
  vec3,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // ----- Constants from spec -----
  const PANEL_WIDTH = 3.2;
  const PANEL_HEIGHT = 2.2;
  const HALF_W = PANEL_WIDTH / 2;
  const HALF_H = PANEL_HEIGHT / 2;
  const CORNER_RADIUS = 0.06;
  const BORDER_WIDTH = 0.006;
  const GRID_PITCH = 0.25;
  const GRID_LINE_OPACITY = 0.06; // 6%
  const GRID_LINE_THICK = 0.002;
  const GHOST_OPACITY_MIN = 0.24;
  const GHOST_OPACITY_MAX = 0.34;
  const GHOST_ANIM_DURATION = 2.4; // seconds (full cycle)

  // ----- Root group -----
  const root = new Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // ----- Panel background with rounded corners, border, radial gradient, grid -----
  const panelGeo = new PlaneGeometry(PANEL_WIDTH, PANEL_HEIGHT);
  const gradStart = new Color('#14141a');
  const gradEnd = new Color('#0b0b10');
  const borderColor = new Color('#26262f');
  const gridColor = new Color('#e8ecf2');

  // Node material construction
  const pos = position; // node representing local position (x, y, z)

  // Edge distance for rounded corners and border
  const edgeDist = min(
    sub(float(HALF_W), abs(pos.x)),
    sub(float(HALF_H), abs(pos.y))
  );

  // Corner mask (inside panel)
  const cornerMask = smoothstep(
    float(CORNER_RADIUS),
    float(CORNER_RADIUS + 0.001),
    edgeDist
  );

  // Border mask (thin rim)
  const borderMask = smoothstep(
    float(0.0),
    float(BORDER_WIDTH),
    edgeDist
  );

  // Radial gradient
  const maxRadius = Math.sqrt(HALF_W * HALF_W + HALF_H * HALF_H);
  const radialDist = length(vec2(pos.x, pos.y)).div(float(maxRadius));
  const radialGrad = mix(gradStart, gradEnd, radialDist);

  // Grid pattern
  const gx = mod(pos.x.add(float(GRID_PITCH / 2)), float(GRID_PITCH)).sub(float(GRID_PITCH / 2));
  const gy = mod(pos.y.add(float(GRID_PITCH / 2)), float(GRID_PITCH)).sub(float(GRID_PITCH / 2));
  const lineX = step(abs(gx), float(GRID_LINE_THICK / 2));
  const lineY = step(abs(gy), float(GRID_LINE_THICK / 2));
  const gridMask = max(lineX, lineY);
  const gridOverlay = mix(
    vec3(0.0, 0.0, 0.0),
    gridColor,
    gridMask.mul(float(GRID_LINE_OPACITY))
  );

  // Combine colors
  const baseColor = mix(radialGrad, borderColor, borderMask);
  const finalColor = mix(baseColor, gridOverlay, gridMask);
  const panelMat = new MeshBasicNodeMaterial();
  panelMat.colorNode = finalColor;
  panelMat.opacityNode = cornerMask;
  panelMat.transparent = true;
  panelMat.depthWrite = false;
  const panelMesh = new Mesh(panelGeo, panelMat);
  root.add(panelMesh);

  // ----- Ghost preview (wireframe card) -----
  const ghostGroup = new Group();
  const GHOST_W = 1.1;
  const GHOST_H = 1.4;
  const ghostStrokeColor = new Color('#e8ecf2');

  // Wireframe rectangle
  const ghostRectGeo = new PlaneGeometry(GHOST_W, GHOST_H);
  const ghostRectMat = new MeshBasicNodeMaterial({
    color: ghostStrokeColor,
    opacity: GHOST_OPACITY_MIN,
    transparent: true,
    wireframe: true,
    depthWrite: false,
  });
  const ghostRect = new Mesh(ghostRectGeo, ghostRectMat);
  ghostGroup.add(ghostRect);

  // Ghost dial circle
  const dialRadius = 0.55 / 2;
  const dialGeo = new CircleGeometry(dialRadius, 32);
  const dialMat = new MeshBasicNodeMaterial({
    color: ghostStrokeColor,
    opacity: GHOST_OPACITY_MIN,
    transparent: true,
    depthWrite: false,
  });
  const dialMesh = new Mesh(dialGeo, dialMat);
  dialMesh.position.set(0, 0, 0.001);
  ghostGroup.add(dialMesh);

  // Ghost text bars (two rectangles)
  const barW = 0.7;
  const barH = 0.06;
  const barGeo = new PlaneGeometry(barW, barH);
  const barMat = new MeshBasicNodeMaterial({
    color: ghostStrokeColor,
    opacity: GHOST_OPACITY_MIN,
    transparent: true,
    depthWrite: false,
  });
  const barTop = new Mesh(barGeo, barMat);
  const barBottom = new Mesh(barGeo, barMat.clone());
  barTop.position.set(0, -dialRadius - 0.04, 0.001);
  barBottom.position.set(0, -dialRadius - 0.12, 0.001);
  ghostGroup.add(barTop, barBottom);

  // Position ghost group left of center with padding 0.5
  const ghostX = -HALF_W + 0.5 + GHOST_W / 2;
  ghostGroup.position.set(ghostX, 0, 0.01);
  root.add(ghostGroup);

  // Ghost breathing opacity animation
  const ghostMaterials = [ghostRectMat, dialMat, barMat, barBottom.material];
  const ghostTL = gsap.timeline({ repeat: -1, yoyo: true });
  ghostTL.to(
    ghostMaterials,
    {
      opacity: GHOST_OPACITY_MAX,
      duration: GHOST_ANIM_DURATION / 2,
      ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    },
    0
  );

  // ----- Text column -----
  const textGroup = new Group();
  const TEXT_PADDING = 0.5;
  const textX = -HALF_W + TEXT_PADDING + GHOST_W + TEXT_PADDING;
  textGroup.position.set(textX, 0, 0.02);
  root.add(textGroup);

  // Helper to create text meshes
  function createText(content, opts) {
    const txt = ctx.fontAtlas.createText(content, opts);
    txt.position.set(0, 0, 0);
    return txt;
  }

  // Headline
  const headline = createText('Your ledger is empty.', {
    fontSize: 34,
    color: '#16161d',
    align: 'left',
  });
  headline.position.set(0, HALF_H - 0.5, 0);
  textGroup.add(headline);

  // Body
  const body = createText(
    'Commissioned pieces and saved references will appear here once you begin.',
    {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'left',
    }
  );
  body.position.set(0, headline.position.y - 0.4, 0);
  textGroup.add(body);

  // CTA Button
  const BUTTON_W = 1.5;
  const BUTTON_H = 0.36;
  const buttonGeo = new PlaneGeometry(BUTTON_W, BUTTON_H);
  const btnTopColor = new Color('#ff4450');
  const btnBottomColor = new Color('#c1121f');
  const btnGradientNode = mix(btnTopColor, btnBottomColor, uv().y);
  const btnMat = new MeshStandardNodeMaterial();
  btnMat.colorNode = btnGradientNode;
  btnMat.emissiveNode = new Color('#ff2a38');
  btnMat.emissiveIntensity = 1.5;
  btnMat.transparent = true;
  btnMat.depthWrite = false;
  const buttonMesh = new Mesh(buttonGeo, btnMat);
  buttonMesh.position.set(0, body.position.y - 0.5, 0);
  root.add(buttonMesh);

  // CTA label
  const ctaLabel = createText('BROWSE THE COLLECTION', {
    fontSize: 13,
    color: '#16161d',
    align: 'center',
  });
  ctaLabel.position.set(0, buttonMesh.position.y, 0.001);
  root.add(ctaLabel);

  // ----- Mount fade‑up animation -----
  const allMaterials = [
    panelMat,
    ...ghostMaterials,
    btnMat,
  ];
  // start invisible & slightly raised
  root.position.y = 0.2;
  allMaterials.forEach((m) => {
    m.transparent = true;
    m.opacity = 0;
  });
  const mountTL = gsap.timeline();
  mountTL.to(
    root.position,
    {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  mountTL.to(
    allMaterials,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );

  // ----- Cleanup ----------
  root.userData.handlers = {}; // no interactions defined
  root.userData.cleanup = () => {
    // kill GSAP timelines
    ghostTL.kill();
    mountTL.kill();
    // dispose geometries & materials
    panelGeo.dispose();
    panelMat.dispose();
    ghostRectGeo.dispose();
    ghostRectMat.dispose();
    dialGeo.dispose();
    dialMat.dispose();
    barGeo.dispose();
    barMat.dispose();
    buttonGeo.dispose();
    btnMat.dispose();
    // dispose any child meshes in textGroup (fontAtlas objects manage their own cleanup)
    // Remove from parent
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
